import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"54、【归妹】 兑下震上","description":"周易尚氏学 - 54、【归妹】 兑下震上","frontmatter":{"title":"54、【归妹】 兑下震上","description":"周易尚氏学 - 54、【归妹】 兑下震上"},"headers":[],"relativePath":"zh/classics/shangshi/059.md","filePath":"zh/classics/shangshi/059.md"}'),s={name:"zh/classics/shangshi/059.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_54、【归妹】-兑下震上" tabindex="-1">54、【归妹】 兑下震上 <a class="header-anchor" href="#_54、【归妹】-兑下震上" aria-label="Permalink to “54、【归妹】 兑下震上”">​</a></h1><p>兑为少女。故曰妹。震为归。妇人谓嫁曰归。故曰归妹。震类长女从长男为恒。则曰利有攸往。兹少女从长男。与恒同耳。乃彖义则与恒相反。曰征凶无攸利何为也。曰恒下巽。巽阴承阳。与上震无一爻不相应。故利有攸往。归妹则巽覆为兑。阴乘阳。初三皆失应。故征凶。巽为利。巽覆故无攸利。又中四爻皆不当位。贞静自守。尚恐有咎。动则悔吝生矣。故征凶不利也。下系云。其为道也屡迁。变动不居。周流六虚。上下无常。刚柔相易。不可为典要。唯变所适。正谓此。恒与归妹。上卦同也。下卦同为二阳一阴也。乃巽则如彼。巽覆则如此。唯变所适也。唯变所适。谓甲卦与乙卦。一爻变动。则吉凶相反。非谓卦无是象。强命某爻变。以成其象也。自汉以来。因误解变动不居。唯变所适二语。援为护符。浪用爻变。以济其穷。前有虞翻。后有焦循。其尤也。</p><p>彖曰。归妹。天地之大义也。天地不交。而万物不兴。归妹。人之终始也。说以动。所归妹也。征凶。位不当也。无攸利。柔乘刚也。</p><p>归妹而后有夫妇。天地者夫妇之义。天地交而后有万物。故归妹为女之终。生人之始。中爻皆不当位。三五皆以柔乘刚。故征凶无攸利也。</p><p>象曰。泽上有雷。归妹。君子以水终知敝。</p><p>女归则永终。兑毁折。故以知敝为戒。</p><p>初九。归妹以娣。破能履。征吉。</p><p>初在兑下。故曰梯。娣者嫡之女弟也。公羊传。诸侯一聘九女。嫁者一娣一侄（左女）。腾者皆有至娣。嫁者谓嫡。嫡及两媵六娃娣共九女。兑折震故跛。然二升五则下成震。震为足。故曰跛能履。征吉也。象曰吉相承。即承二升五而吉也。</p><h3 id="象曰。归妹以娣。以恒也。跛能履。吉相承也。" tabindex="-1">象曰。归妹以娣。以恒也。跛能履。吉相承也。 <a class="header-anchor" href="#象曰。归妹以娣。以恒也。跛能履。吉相承也。" aria-label="Permalink to “象曰。归妹以娣。以恒也。跛能履。吉相承也。”">​</a></h3><p>按初无应。二阳为阻。不能前进。有凶无吉。兹曰吉相承。谓二升五下卦成震。初临重阴。相随而吉。相承者谓二升五吉。初承其后仍吉也。虞翻求其义而不得。强命初爻变阴承阳为说。夫初当位。胡能使变。经义之不明。此等曲说乱之也。以恒盖谓女嫁随娃梯。乃娶妇之常道。说者动以恒卦为解。非。</p><p>九二。眇能视。利幽人之贞。</p><p>二三米高，故曰眇。说文。眇一眇也。能者。以互离也。二应国五，五展为人。克为昧。故曰幽人。利幽人之贞。言利与互相上下。各当位也。</p><h3 id="象曰-利幽人之贞。未变常也。" tabindex="-1">象曰，利幽人之贞。未变常也。 <a class="header-anchor" href="#象曰-利幽人之贞。未变常也。" aria-label="Permalink to “象曰，利幽人之贞。未变常也。”">​</a></h3><p>未变常。言二五相应与乃常道也。</p><p>六三。归妹以须。反归以娣。</p><p>须。说文面毛也。归嫁也。归妹为嫡。今以须之故。反嫁为娣也。伏艮为须。易林同人之否云。牵于虎须。否互艮为虎为须。虞氏训须为需。需待也。六三若有待义。与九四之有待义复矣。易林涣之归妹云。妹为貌执（下心）。败君正色。庄子田子子方老聃新沐。方将被发而乾。华然似非人。华言可怖也。是焦氏亦训须为面毛也。故曰貌华。</p><h3 id="象曰。归妹以须。未当也。" tabindex="-1">象曰。归妹以须。未当也。 <a class="header-anchor" href="#象曰。归妹以须。未当也。" aria-label="Permalink to “象曰。归妹以须。未当也。”">​</a></h3><p>未当言不宜有是恶象也。困上六当位矣。象曰未当也。义与此同。革传曰革而当。义皆同宜。后雅丽堂集解本见虞注作位未当。竟于象传添一位字。岂知正文若作位未当。释文早言之矣。今释文无有。可证虞本亦无位字。雅丽本皆从惠栋校。改字甚多。昔人谓惠氏乱经。兹更添字。宜罪之者多也。</p><p>九四。归妹愆期。返归有时。</p><p>震为时。坎陷故愆期。愆过也。愆期故迟归待时。待升五也。又下无应。亦衍期之一因。卦四时俱备。故曰有时。升五则时至矣。</p><h3 id="象曰。想期之志。有待而行也。" tabindex="-1">象曰。想期之志。有待而行也。 <a class="header-anchor" href="#象曰。想期之志。有待而行也。" aria-label="Permalink to “象曰。想期之志。有待而行也。”">​</a></h3><p>坎为志。震为行。有待而行者。待升五也。</p><p>六五。帝已归妹。其君之袂。不如其娣之袂良。月既望吉。</p><p>震为帝。故曰帝乙。帝乙汤也。京房易载基嫁妹之辞。是汤曾嫁妹。故曰帝乙归妹。震为君为袂。而震亦为口。袂袖口也。袂在五震。故日君袂。在二兑。故曰棵袂。皆取象于口。乃五阴二阳。故君袂不如姊良。坎为月。为中。震东兑西。坎月离日。东西相望。正望日也。惟五居坎末。时已过中。故曰既望。既望从孟、荀读。虞作几。京作近。晁说之云。古文近既读同。孟云既望者。十六日也。五得中有应故吉。震君震袂震口象皆失传。说详焦氏易诂。</p><h3 id="象曰。帝已归妹。不如其梯之袂良也。其位在中。以贵行也。" tabindex="-1">象曰。帝已归妹。不如其梯之袂良也。其位在中。以贵行也。 <a class="header-anchor" href="#象曰。帝已归妹。不如其梯之袂良也。其位在中。以贵行也。" aria-label="Permalink to “象曰。帝已归妹。不如其梯之袂良也。其位在中。以贵行也。”">​</a></h3><p>虽不正而得中。中五位尊。故曰贵。</p><p>站长：孟、荀可能是指孟喜和荀爽，他们是西汉时期的易学家。应该当作「既望」，巽也为月始缺，如小畜「既雨既处...月既望」同理。</p><p>上六。女筐无实。士刲羊无血。无攸利。</p><p>下兑为女。震为筐。女在下。筐在上。故曰女承筐。乃上不应三。故无实。震为虚。亦无实也。震为士。兑为羊。为斧。为毁折。故曰士刲羊。乃三不应上。故无血。坎为血。三体离。坎伏。故无血。此与失九二。因爻无应。即就无应取义。旧解坐不知此。故说之永不能通。巽为利。巽伏上下失应。故无攸利。震虚象失传。虞翻用卦变成坤。取虚象。岂知震为苍茛竹为苇。皆取其中虚。况象传曰虚筐。亦以震为虚。</p><h3 id="象曰。上六元实。承虚筐也。" tabindex="-1">象曰。上六元实。承虚筐也。 <a class="header-anchor" href="#象曰。上六元实。承虚筐也。" aria-label="Permalink to “象曰。上六元实。承虚筐也。”">​</a></h3><p>象明言震虚。故知虞氏非。</p>',31)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
